script:
frappe.ui.form.on('Harvest Record', {
	quantity_harvested: function(frm) {
		// Calculate yield per unit area
		if (frm.doc.quantity_harvested && frm.doc.area_harvested && frm.doc.area_harvested > 0) {
			frm.set_value('yield_per_unit_area',
				frm.doc.quantity_harvested / frm.doc.area_harvested);
		}
	},

	area_harvested: function(frm) {
		// Calculate yield per unit area
		if (frm.doc.quantity_harvested && frm.doc.area_harvested && frm.doc.area_harvested > 0) {
			frm.set_value('yield_per_unit_area',
				frm.doc.quantity_harvested / frm.doc.area_harvested);
		}
	},

	field: function(frm) {
		// Auto-populate farm from field
		if (frm.doc.field && !frm.doc.farm) {
			frappe.db.get_value('Field', frm.doc.field, 'farm', (r) => {
				if (r && r.farm) {
					frm.set_value('farm', r.farm);
				}
			});
		}
	},

	before_submit: function(frm) {
		// Check for PHI compliance warning
		if (frm.doc.crop_project && frm.doc.field) {
			frappe.call({
				method: 'frappe.client.get_list',
				args: {
					doctype: 'Field Operation Log',
					filters: {
						field: frm.doc.field,
						crop_project: frm.doc.crop_project,
						operation_type: 'Spraying',
						docstatus: 1
					},
					fields: ['name', 'operation_date', 'pre_harvest_interval_days'],
					order_by: 'operation_date desc',
					limit: 1
				},
				callback: function(r) {
					if (r.message && r.message.length > 0) {
						let spray = r.message[0];
						if (spray.pre_harvest_interval_days) {
							let harvest_date = frappe.datetime.str_to_obj(frm.doc.harvest_date);
							let spray_date = frappe.datetime.str_to_obj(spray.operation_date);
							let days_diff = frappe.datetime.get_day_diff(harvest_date, spray_date);

							if (days_diff < spray.pre_harvest_interval_days) {
								frappe.msgprint({
									title: 'PHI Warning',
									indicator: 'red',
									message: `Pre-Harvest Interval (PHI) not met! Last spray was ${days_diff} days ago, but ${spray.pre_harvest_interval_days} days required.`
								});
							}
						}
					}
				}
			});
		}
	}
});

// Grade Distribution child table
frappe.ui.form.on('Harvest Grade Distribution', {
	quantity: function(frm, cdt, cdn) {
		// Auto-calculate percentage
		let row = locals[cdt][cdn];
		if (frm.doc.quantity_harvested && frm.doc.quantity_harvested > 0) {
			frappe.model.set_value(cdt, cdn, 'percentage',
				(row.quantity / frm.doc.quantity_harvested) * 100);
		}

		// Refresh total
		frm.refresh_field('grade_distribution');
	}
});
